    from typing import List
    if n < 0:
        raise ValueError("Degree n must be non-negative")
    if len(coeffs) != n + 1:
        raise ValueError(f"Expected {n + 1} coefficients for degree {n}, got {len(coeffs)}")

    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue

        # Determine the sign
        if not terms:
            # First term
            if coeff < 0:
                sign = '-'
            else:
                sign = ''
        else:
            if coeff < 0:
                sign = '-'
            else:
                sign = '+'

        # Determine the coefficient part
        abs_coeff = abs(coeff)
        if degree > 0 and abs_coeff == 1:
            coeff_part = ''
        else:
            coeff_part = str(abs_coeff)

        # Determine the variable part
        if degree == 0:
            var_part = ''
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = f'x^{degree}'

        term = sign + coeff_part + var_part
        terms.append(term)

    if not terms:
        return '0'

    return ''.join(terms)

